\u0065\u0026\u007e\u006d\u0063\u0072\u0076\u006e\u0074\u0032\u006c\u002b\u0035\u0078\u0046\u0031\u0048\u0071\u005e\u0060\u0030\u0021\u0060\u002a\u0034\u004c\u0022\u005d\u0066\u0074\u0050\u0076\u002f\u0048\u0059\u004d\u0031\u0021\u0021\u0041\u0076\u0026\u006b\u006f\u0035\u0040\u0030\u0054\u003f\u0065\u0051\u0078\u0049\u007c\u0066\u007b\u0060\u0031\u005a\u005b\u005b\u004f\u0060\u0066\u006e\u006e\u0021\u004c\u0077\u0070\u006a\u0060\u004f\u0063\u0037\u006b\u0062\u0066\u004b\u002c\u0031\u0058\u0074\u004a\u0055\u0043\u0025\u005e\u005b\u0035\u0055\u0044\u006d\u0036\u0058\u0071\u007d\u0049\u0062\u0033\u006a\u0030\u003c\u0057\u006f\u0045\u0026\u0038\u002e\u0043\u0065\u003c\u0059\u0050\u003a\u005e\u0075\u0035\u007a\u004a\u0049\u0065\u007b\u004a\u0029\u005a\u005a\u0048\u0050\u0064\u004b\u0065\u007b\u0025\u0050\u0034\u006c\u005a\u0056\u0026\u0069\u0036\u0053\u0053\u0024\u0026\u0067\u0035\u0066\u0070\u0060\u0070\u0070\u007a\u0052\u0062\u0066\u0040\u002c\u0030\u003e\u006c\u0034\u0079\u004a\u0061\u0046\u0038\u0040\u0051\u006f\u002e\u007b\u004d\u0066\u0047\u002c\u0067\u0064\u0047\u0043\u003e\u004d\u0028\u0045\u004f\u0032\u0068\u0029\u0055\u0034\u0021\u0040\u0032\u003d\u0053\u0049\u006f\u006b\u007c\u0066\u004d\u0078\u005d\u004a\u0029\u0050\u005f\u002f\u006d\u0035\u005f\u005f\u0070\u006e\u0039\u002a\u005f\u003b\u0036\u004e\u005e\u0079\u003d\u005b\u002c\u003d\u006e\u006c\u0078\u0031\u0053\u0029\u0022\u0048\u0067\u0049\u0072\u0072\u004d\u0047\u006f\u0029\u005b\u0075\u0078\u005f\u0034\u0074\u005e\u0028\u007b\u0063\u0025\u0047\u0073\u0051\u003e\u0038\u0074\u0043\u006d\u0025\u0039\u004a\u0067\u0024\u003c\u004b\u007d\u0064\u005f\u0079\u0063\u0049\u002a\u0056\u0058\u0033\u0036\u0031\u003a\u0034\u003d\u0039\u0048\u003d\u0030\u003f\u0052\u0076\u0025\u004a\u0047\u0026\u0078\u003b\u0038\u003a\u0046\u006a\u002b\u0042\u0064\u0053\u0041\u0033\u0067\u004e\u004f\u0041\u0041\u007c\u0031\u0034\u002e\u002a\u007c\u003c\u002c\u0076\u0029\u0033\u007b\u0030\u0050\u003f\u0055\u0035\u007d\u002c\u0043\u005b\u004c\u002a\u0021\u004d\u0039\u0063\u003a\u002c\u0048\u006b\u004b\u0065\u0065\u0034\u005b\u0079\u0051\u004a\u0047\u0075\u0057\u003c\u0050\u0078\u006a\u0052\u0037\u0046\u0061\u004b\u0034\u0036\u0052\u0045\u003a\u0035\u0021\u0029\u004c\u007c\u005d\u0068\u0078\u0070\u0044\u002b\u0025\u0055\u0037\u0077\u0068\u0059\u0052\u0035\u004c\u0072\u0051\u0045\u0076\u003a\u0021\u004b\u0025\u0045\u004b\u0051\u006e\u006c\u007a\u004e\u0051\u0031\u005d\u0046\u004d\u0030\u0042\u0035\u0049\u003c\u005a\u005d\u0076\u0075\u0062\u0063\u0051\u006f\u0074\u0070\u006d\u0079\u0060\u0021\u004e\u003e\u0051\u0039\u005d\u0068\u0062\u004f\u0026\u0075\u0076\u0022\u0072\u0036\u0069\u0021\u0057\u006a\u004a\u002b\u002b\u0045\u0051\u003d\u004e\u0074\u0040\u003e\u0079\u005a\u0030\u0054\u003e\u006b\u007d\u0071\u0024\u0068\u0037\u007a\u0026\u0075\u004c\u0056\u0059\u006f\u006f\u0064\u0063\u0078\u0031\u005e\u005a\u0077\u006d\u006a\u0053\u0046\u0037\u003a\u0055\u0071\u0059\u0034\u0066\u0077\u0075\u0054\u005a\u0051\u0065\u007c\u0060\u0057\u0048\u007e\u0032\u0051\u0062\u006d\u0042\u0065\u0070\u003c\u002e\u0044\u0028\u004f\u0033\u0056\u0077\u0021\u007e\u0076\u0028\u006e\u003a\u0042\u0028\u006e\u006e\u0052\u004e\u0064\u0039\u002b\u0042\u007b\u002b\u002e\u006f\u0077\u0076\u007b\u0078\u0028\u0024\u0058\u0064\u004d\u0063\u0044\u007e\u007c\u002f\u004a\u0064\u0066\u0046\u0035\u005f\u0059\u0057\u0074\u0065\u005e\u0069\u002f\u0044\u0061\u005b\u0057\u0056\u005a\u0034\u007b\u0031\u002a\u0072\u0078\u006c\u0054\u002e\u0052\u0037\u004a\u0032\u007c\u0034\u0040\u0056\u0028\u0064\u007b\u0033\u005d\u0047\u0022\u007a\u0062\u0074\u0055\u0045\u0040\u0069\u005f\u006b\u002a\u003a\u004b\u0077\u002b\u0070\u0064\u0047\u006a\u0069\u005f\u006d\u002a\u0024\u0051\u006c\u0050\u006d\u007e\u0060\u0057\u0047\u007c\u0079\u0032\u002b\u0069\u0040\u007b\u006e\u0035\u006a\u0039\u0056\u0029\u0024\u003e\u003a\u0040\u002f\u0028\u007b\u0078\u0039\u0062\u0076\u0022\u006d\u0071\u0073\u0059\u0022\u0072\u0055\u0076\u0047\u005a\u006c\u005f\u0044\u0055\u0079\u0024\u004a\u007e\u0042\u005a\u0037\u004d\u0024\u0026\u0048\u006f\u0022\u0056\u007d\u0030\u005f\u007b\u0042\u0050\u0022\u004e\u007b\u006a\u0078\u0072\u0074\u0059\u0042\u003a\u0066\u0053\u007c\u0077\u0046\u006e\u0037\u002c\u0024\u0022\u005b\u0077\u0075\u0076\u0078\u0049\u0065\u004d\u002f\u002b\u0067\u0028\u0070\u0060\u004d\u0058\u007b\u0061\u0024\u0038\u0035\u006a\u002f\u0024\u005a\u003a\u002b\u0026\u005d\u002c\u0079\u0028\u0059\u003b\u0046\u0043\u0045\u0029\u006e\u0035\u0041\u0023\u0037\u007a\u005a\u0076\u0073\u0064\u0065\u0026\u004d\u0046\u0030\u006a\u003f\u007b\u005a\u003a\u0070\u0053\u003d\u007d\u0036\u0048\u0053\u005b\u007e\u006d\u0064\u0042\u0025\u0065\u004a\u0043\u006d\u0075\u005b\u0046\u002a\u0026\u003d\u003f\u003c\u0062\u0061\u004d\u0065\u004a\u005b\u006b\u0025\u0069\u0055\u0052\u0051\u0077\u0026\u0070\u005d\u006e\u0061\u002b\u004e\u0071\u0079\u0045\u005b\u0034\u0065\u0028\u0052\u007c\u002c\u006e\u0028\u0036\u0069\u005e\u002b\u0037\u0047\u0062\u0036\u003c\u003e\u0076\u003b\u002e\u0033\u006a\u007d\u0034\u0073\u0043\u0071\u0062\u003b\u005e\u0030\u0028\u004c\u006c\u0075\u0067\u004b\u0039\u003f\u0038\u0045\u0052\u002a\u005f\u0042\u002f\u003a\u006a\u0032\u0052\u002c\u0066\u006c\u0077\u003e\u0062\u003f\u005d\u004a\u0060\u002a\u0026\u0066\u003f\u0076\u007b\u005e\u002f\u0057\u0066\u0060\u006e\u0068\u0026\u003b\u0063\u0075\u007c\u0033\u0072\u004b\u006f\u004f\u0053\u0068\u0036\u0072\u0064\u005f\u0049\u0036\u0039\u0031\u003c\u0059\u0029\u004b\u0070\u0034\u0071\u004c\u006e\u005f\u0047\u0073\u004c\u0054\u0041\u0036\u006b\u006f\u004a\u0040\u0026\u002c\u004f\u006f\u005e\u003f\u0073\u0077\u0033\u0026\u0024\u0056\u0041\u0078\u0060\u006d\u005e\u005f\u0022\u004a\u0048\u0066\u005b\u0045\u0046\u0059\u007b\u003a\u0079\u0057\u0077\u0033\u0069\u0063\u0064\u003c\u0076\u004b\u003b\u0060\u0047\u003e\u004e\u0072\u0079\u0070\u002a\u0060\u0065\u0053\u003a\u002f\u0072\u0079\u0022\u003c\u006e\u004f\u0079\u006a\u004c\u0036\u0054\u0068\u0059\u0059\u0069\u002a\u003c\u002e\u004a\u004d\u006f\u0063\u0038\u004f\u0079\u006f\u0025\u0055\u004c\u006f\u0075\u007a\u002e\u006b\u002c\u0060\u0065\u0075\u006e\u004b\u002e\u004a\u007b\u0056\u0064\u004f\u0079\u002a\u0054\u007c\u0065\u0032\u004c\u0047\u003d\u002a\u0021\u002e\u004a\u003f\u0040\u0035\u0065\u0043\u0053\u0032\u0029\u007a\u002c\u0074\u0059\u0060\u0065\u007d\u0059\u0058\u004b\u0072\u0056\u0064\u004f\u0079\u0052\u0023\u0035\u0065\u006c\u006b\u004a\u006f\u0069\u0063\u0073\u0028\u002c\u002c\u0032\u0070\u006f\u0062\u005b\u005d\u0022\u0053\u0029\u0033\u0046\u003b\u0065\u0049\u003e\u004c\u0035\u0025\u0037\u007a\u0064\u007e\u005e\u0065\u005d\u0041\u006c\u005b\u0066\u0028\u0058\u006c\u0073\u0058\u0075\u0068\u004c\u0037\u0043\u004e\u0057\u005d\u0050\u0077\u0050\u0039\u003a\u0037\u007a\u0030\u0028\u0029\u0050\u0033\u0042\u006c\u0067\u0047\u0036\u0075\u0034\u005f\u0033\u0075\u0032\u0076\u0037\u0065\u0038\u0072\u0039\u003c\u0057\u0023\u0063\u003e\u0054\u0040\u0062\u0067\u0063\u003a\u006b\u0036\u004c\u0030\u0025\u0036\u0029\u007a\u0050\u0042\u0060\u007e\u0021\u0051\u007b\u0028\u003c\u004f\u0069\u0037\u0078\u007c\u002f\u0060\u0038\u0044\u0073\u006c\u0025\u004e\u0069\u0059\u0035\u0062\u002e\u007e\u004b\u0043\u004c\u0057\u007c\u002f\u0060\u0038\u0044\u0030\u0040\u0062\u003b\u0069\u0064\u0077\u006a\u0070\u0038\u0076\u0069\u0044\u0039\u0034\u004f\u006a\u0035\u0043\u003c\u005d\u0030\u004c\u002f\u0066\u0053\u002f\u0048\u0071\u0055\u002e\u003a\u0062\u003b\u0069\u006d\u0022\u006d\u005d\u005d\u0030\u004c\u002f\u0066\u0053\u002f\u005a\u007d\u0036\u006e\u003a\u0062\u003b\u0062\u0026\u0039\u0046\u0066\u002c\u0021\u0043\u0060\u0063\u0050\u002f\u0033\u004e\u0046\u0079\u007b\u002f\u0073\u0041\u0028\u0021\u0043\u0060\u0063\u0050\u002f\u0033\u0068\u002a\u0038\u005e\u0067\u0030\u0061\u002c\u003a\u0076\u0024\u002f\u0047\u007e\u0042\u0077\u0071\u0072\u0058\u003d\u003f\u0079\u0076\u002c\u0022\u003f\u006d\u0048\u0021\u0022\u004f\u004f\u0056\u003a\u0033\u0056\u0054\u0062\u0068\u007a\u004c\u0077\u005b\u0040\u0035\u0073\u0059\u0047\u0074\u0032\u006b\u0079\u0041\u0048\u0077\u0066\u007c\u0040\u0068\u007b\u0061\u0023\u006b\u0072\u003e\u0038\u0077\u004c\u006e\u0066\u007d\u0033\u002c\u0056\u002e\u0052\u0077\u0055\u007d\u0047\u0033\u0050\u0028\u003f\u0039\u0042\u0048\u002c\u0021\u0057\u007a\u0039\u0023\u004f\u0049\u0068\u0058\u0050\u002c\u0063\u003a\u0056\u0073\u007a\u0030\u007c\u0058\u005a\u007a\u0044\u0071\u0075\u0043\u0056\u0072\u0055\u003e\u005e\u0035\u0046\u0063\u0071\u0048\u007b\u0040\u0055\u005d\u006c\u0061\u0021\u0028\u0062\u0035\u0021\u0069\u0063\u003a\u004f\u004e\u0077\u0059\u0053\u006f\u0057\u007a\u003f\u004b\u0036\u0040\u004e\u007d\u0026\u003c\u007d\u007e\u0024\u0024\u0048\u0025\u0025\u0039\u0037\u0042\u0026\u0038\u0060\u007d\u0065\u0052\u0065\u0038\u004a\u0078\u0071\u0035\u0077\u0070\u004c\u0077\u004c\u0066\u0061\u0071\u006b\u006f\u004f\u0043\u0042\u0037\u0066\u004e\u0044\u0036\u003e\u002b\u003f\u0025\u0065\u002f\u006d\u0060\u006d\u0038\u0038\u0025\u0065\u005f\u0051\u006d\u007a\u002b\u0025\u0075\u004f\u005f\u0059\u002b\u0058\u006b\u0045\u0064\u0054\u0052\u003e\u0073\u0041\u003b\u005e\u0075\u004d\u0077\u003a\u007e\u0065\u0036\u0064\u0068\u004e\u0069\u0023\u0071\u003d\u0068\u005e\u0046\u0050\u0064\u0033\u0024\u006f\u0029\u002f\u0073\u004e\u005e\u002a\u0070\u0048\u0070\u0053\u0050\u0061\u0041\u003f\u0073\u002c\u006b\u0038\u0052\u006a\u004d\u002b\u007a\u007a\u002e\u0043\u007b\u004a\u0062\u007c\u002a\u0077\u007d\u0069\u0023\u0053\u0065\u0029\u0036\u0062\u0046\u0048\u002a\u0070\u0024\u0065\u0033\u0044\u005b\u002c\u0043\u0025\u006d\u0053\u0055\u0043\u0061\u004a\u0034\u0029\u0065\u0073\u005e\u004b\u0038\u007d\u002f\u0036\u004f\u0028\u0026\u0054\u0033\u006e\u0031\u002c\u0029\u007c\u0063\u004a\u0075\u007b\u0037\u0052\u0042\u002e\u004b\u0025\u0031\u003a\u005d\u002c\u005f\u0031\u0071\u002f\u0030\u005f\u002e\u0055\u0056\u006d\u0062\u004b\u007d\u0026\u0055\u004e\u0071\u0047\u0045\u006b\u0061\u0045\u0059\u0021\u0061\u004a\u004e\u007d\u004d\u006c\u002a\u003f\u004e\u004c\u007e\u0075\u003f\u006d\u0034\u006c\u0036\u0037\u005b\u0047\u0055\u0038\u0045\u0069\u004f\u0057\u0024\u004f\u0045\u0045\u0042\u007d\u0066\u004c\u0023\u0033\u0032\u0075\u0064\u005a\u006b\u0038\u007e\u0031\u005f\u006b\u003c\u006f\u003f\u003a\u004d\u004c\u007b\u0034\u0066\u0070\u0060\u006c\u0026\u005e\u006f\u006b\u0075\u006e\u0037\u0028\u0053\u0044\u006a\u0068\u006f\u0061\u0041\u0028\u005a\u0024\u0048\u0055\u0065\u0042\u0042\u006c\u006d\u0072\u0073\u0050\u0056\u006d\u006b\u0047\u0025\u0065\u006a\u0065\u0049\u0047\u003f\u006f\u003f\u007a\u0059\u004a\u0071\u005b\u005e\u005b\u007b\u004e\u003a\u007d\u003b\u007a\u0040\u0028\u005a\u0024\u0048\u0055\u0065\u002a\u007e\u006c\u0071\u0049\u0062\u005f\u0056\u006d\u006b\u0047\u0025\u0065\u0067\u0028\u0070\u0060\u004d\u0058\u007b\u0061\u0024\u0038\u0060\u002e\u0035\u005b\u0070\u006f\u002e\u0052\u004d\u002b\u0055\u005a\u0052\u0072\u0032\u0038\u004d\u0058\u0039\u0031\u003a\u0077\u0046\u0064\u0053\u0023\u0053\u0049\u0040\u006a\u006f\u0057\u0026\u0069\u0036\u0057\u0030\u004b\u0072\u0050\u0072\u003e\u0024\u0033\u0044\u0078\u0031\u007b\u003b\u0056\u007b\u005e\u0040\u0072\u0029\u0075\u0029\u004d\u0048\u0033\u0033\u0079\u004d\u0071\u0031\u007b\u0028\u0036\u006b\u0059\u003c\u0025\u0052\u006b\u002c\u0079\u003f\u002e\u005a\u0053\u006b\u0076\u0034\u0045\u0072\u002b\u007c\u006f\u005b\u0041\u0054\u003e\u0060\u0034\u0023\u0059\u0046\u002c\u0062\u0025\u0049\u004d\u0067\u0024\u0051\u006a\u0025\u007c\u0053\u0069\u0062\u006d\u0021\u005b\u0069\u005a\u007e\u0035\u0042\u0058\u0026\u007d\u0054\u0023\u0025\u0050\u0071\u002e\u004f\u002c\u0044\u0047\u004a\u0056\u002f\u0078\u0078\u0042\u0029\u005b\u0076\u007c\u0029\u002a\u0023\u0059\u0046\u0024\u005b\u0067\u0037\u0040\u0047\u0073\u0044\u0059\u007e\u002f\u006b\u003c\u0077\u0054\u002f\u0040\u0039\u0071\u005b\u006e\u0029\u005d\u005e\u0040\u0069\u0074\u0039\u005a\u007a\u0053\u0031\u0041\u005e\u002a\u007c\u003b\u004a\u004a\u0048\u0050\u007a\u003e\u002b\u005f\u0042\u0076\u0061\u003d\u003a\u006e\u007b\u005d\u0026\u0037\u0060\u003a\u003d\u0072\u0062\u0075\u0035\u0038